/**
 * WasmDevice: KodeDevice over the firmware team's browser adapter (runtime/web-adapter, `DotbenchDevice`).
 * The adapter is imported lazily (it is copied into src/generated by scripts/sync-adapter.mjs) so the page
 * and the mock never load it. Tests pass `createAdapter` with a fake.
 *
 * What does not fit KodeDevice 1:1 is exposed through `RealDevice` (extra members, see below):
 *  - status 'restart-requested' is surfaced as 'booting' plus a log line carrying the reason;
 *    the adapter's auto-restart does the actual reboot,
 *  - crash reason, runtime-support problems, worker/memory numbers, device export/import.
 */
import { packRegions, unpackRegions } from '../lib/devicefile';
import type { AdapterDevice, AdapterLogLine, AdapterOutputs, AdapterStatusDetail } from './adapter-types';
import { Atom, LogBuffer } from './observable';
import {
  SCREEN_HEIGHT,
  SCREEN_WIDTH,
  type ButtonId,
  type DeviceInfo,
  type DeviceStatus,
  type Frame,
  type HardwareAreas,
  type KodeDevice,
  type LoadOptions,
  type LogStream,
  type Observable,
  type Rgb,
} from './types';

export class NotWiredError extends Error {
  constructor() {
    super('WebAssembly adapter not wired yet.');
    this.name = 'NotWiredError';
  }
}

// ------------------------------------------------------------------ support

export type RuntimeProblemCode = 'no-webassembly' | 'not-isolated' | 'no-shared-array-buffer' | 'no-wasm-threads' | 'no-decompression-stream';

export interface RuntimeEnv {
  crossOriginIsolated?: boolean;
  SharedArrayBuffer?: unknown;
  WebAssembly?: { Memory: new (d: { initial: number; maximum: number; shared: boolean }) => unknown };
  DecompressionStream?: unknown;
}

/** What the browser lacks to run a .dotbench (empty = fine). Pure, so it is unit-tested. */
export function checkRuntime(env: RuntimeEnv = globalThis as unknown as RuntimeEnv): RuntimeProblemCode[] {
  const out: RuntimeProblemCode[] = [];
  if (typeof env.WebAssembly === 'undefined') return ['no-webassembly'];
  if (!env.crossOriginIsolated) out.push('not-isolated');
  if (typeof env.SharedArrayBuffer === 'undefined') out.push('no-shared-array-buffer');
  else {
    try {
      new env.WebAssembly.Memory({ initial: 1, maximum: 1, shared: true });
    } catch {
      out.push('no-wasm-threads');
    }
  }
  if (typeof env.DecompressionStream === 'undefined') out.push('no-decompression-stream');
  return out;
}

export class UnsupportedRuntimeError extends Error {
  constructor(readonly problems: RuntimeProblemCode[]) {
    super(`This browser cannot run apps: ${problems.join(', ')}`);
    this.name = 'UnsupportedRuntimeError';
  }
}

// ------------------------------------------------------------------- device

export interface StatusDetail {
  status: DeviceStatus;
  /** crash cause, or the reset reason while a restart is in progress */
  reason?: string;
  /** true while the firmware asked for a restart and the adapter is rebooting it */
  restarting?: boolean;
}

/** What the page can additionally do with the real device (the mock has none of this). */
export interface RealDevice extends KodeDevice {
  readonly detail: Observable<StatusDetail>;
  /** Empty when this browser can run apps. Checked once at construction. */
  readonly unsupported: readonly RuntimeProblemCode[];
  stats(): { workers: number; memoryBytes: number };
  releaseAll(): void;
  exportDevice(): Promise<{ data: Uint8Array; extension: string }>;
  importDevice(data: Uint8Array): Promise<void>;
}
export const isRealDevice = (d: KodeDevice): d is RealDevice => d.info.kind === 'wasm' && 'detail' in d;

export interface WasmDeviceOptions {
  createAdapter?: () => Promise<AdapterDevice>;
  env?: RuntimeEnv;
}

const defaultAdapter = async (): Promise<AdapterDevice> => {
  const m = await import('../generated/web-adapter/dotbench-device.js');
  return new m.DotbenchDevice({ autoRestart: true });
};

export class WasmDevice implements RealDevice {
  readonly info: DeviceInfo = { kind: 'wasm', label: 'WebAssembly', runsBundles: true };
  readonly unsupported: readonly RuntimeProblemCode[];

  private _status = new Atom<DeviceStatus>('idle');
  private _detail = new Atom<StatusDetail>({ status: 'idle' });
  private _appName = new Atom<string | null>(null);
  private _backlight = new Atom(100);
  private _panelOn = new Atom(true);
  private _led = new Atom<Rgb>({ r: 0, g: 0, b: 0 });
  private _haptic = new Atom(0);
  private _log = new LogBuffer();

  readonly status: Observable<DeviceStatus> = this._status;
  readonly detail: Observable<StatusDetail> = this._detail;
  readonly appName: Observable<string | null> = this._appName;
  readonly backlight: Observable<number> = this._backlight;
  readonly panelOn: Observable<boolean> = this._panelOn;
  readonly led: Observable<Rgb> = this._led;
  readonly haptic: Observable<number> = this._haptic;
  readonly log: LogStream = this._log;
  readonly areas: Readonly<Partial<HardwareAreas>>;

  private adapter: AdapterDevice | null = null;
  private adapterPromise: Promise<AdapterDevice> | null = null;
  private offs: (() => void)[] = [];
  private disposed = false;
  private data = new Uint8ClampedArray(new ArrayBuffer(SCREEN_WIDTH * SCREEN_HEIGHT * 4));
  private blank: Frame;
  private frame: Frame;
  private adapterSeq = -1;
  private outSeq = 0;

  constructor(private opts: WasmDeviceOptions = {}) {
    this.unsupported = checkRuntime(opts.env);
    const black = new Uint8ClampedArray(new ArrayBuffer(SCREEN_WIDTH * SCREEN_HEIGHT * 4));
    for (let i = 3; i < black.length; i += 4) black[i] = 255;
    this.blank = { seq: 0, width: SCREEN_WIDTH, height: SCREEN_HEIGHT, data: black };
    this.frame = this.blank;
    // areas: whatever JS glue the running app registered, looked up live (null/absent when none)
    this.areas = new Proxy({} as Partial<HardwareAreas>, {
      get: (_t, key) => (typeof key === 'string' ? (this.adapter?.area(key) ?? undefined) : undefined),
      has: (_t, key) => typeof key === 'string' && !!this.adapter?.area(key),
    });
  }

  private ensureAdapter(): Promise<AdapterDevice> {
    if (this.disposed) return Promise.reject(new Error('device disposed'));
    this.adapterPromise ??= (this.opts.createAdapter ?? defaultAdapter)().then((a) => {
      this.adapter = a;
      this.offs.push(
        a.on('status', (s: AdapterStatusDetail) => this.onStatus(s)),
        a.on('log', (l: AdapterLogLine) => this._log.push(l.level, l.text, l.ts)),
        a.on('outputs', (o: AdapterOutputs) => this.applyOutputs(o)),
      );
      return a;
    });
    return this.adapterPromise;
  }

  private onStatus(s: AdapterStatusDetail): void {
    const a = this.adapter;
    if (s.status === 'restart-requested') {
      const to = s.target ? ` -> ${s.target}` : '';
      this._log.push('info', `restart requested: ${s.reason ?? 'unknown'}${to}`);
      this._detail.set({ status: 'booting', reason: s.reason, restarting: true });
      this._status.set('booting');
      return;
    }
    this._detail.set(s.status === 'crashed' ? { status: 'crashed', reason: s.reason } : { status: s.status });
    this._status.set(s.status);
    if (a?.appName) this._appName.set(a.appName);
    if (s.status === 'running') this.applyOutputs(a!.outputs());
    if (s.status === 'idle' || s.status === 'crashed') {
      this._led.set({ r: 0, g: 0, b: 0 });
      this._haptic.set(0);
    }
    if (s.status === 'idle') {
      this.adapterSeq = -1;
      this.frame = { ...this.blank, seq: ++this.outSeq };
    }
  }

  private applyOutputs(o: AdapterOutputs): void {
    const cur = this._led.get();
    if (cur.r !== o.led.r || cur.g !== o.led.g || cur.b !== o.led.b) this._led.set({ r: o.led.r, g: o.led.g, b: o.led.b });
    this._haptic.set(o.haptic);
    this._backlight.set(o.backlight);
    this._panelOn.set(o.panelOn);
  }

  // lifecycle ---------------------------------------------------------------
  async load(bundle: ArrayBuffer, options: LoadOptions): Promise<void> {
    if (this.unsupported.length) throw new UnsupportedRuntimeError([...this.unsupported]);
    const a = await this.ensureAdapter();
    this._log.push('info', `loading ${options.name}`);
    await a.load(bundle);
    this._appName.set(a.appName ?? options.name);
  }
  async start(): Promise<void> {
    const a = this.adapter;
    if (!a) throw new Error('nothing loaded');
    await a.start();
  }
  async restart(): Promise<void> {
    const a = this.adapter;
    if (!a) throw new Error('nothing loaded');
    await a.restart();
  }
  stop(): void {
    this.adapter?.stop();
  }
  dispose(): void {
    this.disposed = true;
    for (const o of this.offs) o();
    this.offs = [];
    this.adapter?.dispose();
    this.adapter = null;
  }

  // screen ------------------------------------------------------------------
  getFrame(): Frame {
    const a = this.adapter;
    if (!a || a.status === 'idle') return this.frame;
    const seq = a.copyFrame(this.data, this.adapterSeq);
    if (seq !== this.adapterSeq) {
      this.adapterSeq = seq;
      this.frame = { seq: ++this.outSeq, width: SCREEN_WIDTH, height: SCREEN_HEIGHT, data: this.data };
    }
    return this.frame;
  }

  // inputs ------------------------------------------------------------------
  setButton(id: ButtonId, pressed: boolean): void {
    this.adapter?.button(id, pressed);
  }
  setTouch(x: number, y: number, down: boolean): void {
    this.adapter?.touch(x, y, down);
  }
  releaseAll(): void {
    this.adapter?.releaseAll();
  }

  // console / time ------------------------------------------------------------
  sendConsole(line: string): void {
    // the adapter echoes it as an 'input' line through the log event
    if (this.adapter) this.adapter.sendConsole(line);
    else this._log.push('input', line);
  }
  time(): number {
    return this.adapter?.time() ?? Date.now();
  }

  stats(): { workers: number; memoryBytes: number } {
    return { workers: this.adapter?.workerCount ?? 0, memoryBytes: this.adapter?.wasmMemoryBytes ?? 0 };
  }

  // device persistence --------------------------------------------------------
  /** Prefers a whole-device export if the adapter has one (another engineer is adding it); else the raw persistent regions. */
  async exportDevice(): Promise<{ data: Uint8Array; extension: string }> {
    const a = await this.ensureAdapter();
    if (typeof a.exportDevice === 'function') {
      const r = await a.exportDevice();
      const data = r instanceof Blob ? new Uint8Array(await r.arrayBuffer()) : r instanceof Uint8Array ? r : new Uint8Array(r);
      return { data, extension: 'dotbench-device' };
    }
    if (typeof a.exportPersist === 'function') return { data: packRegions(a.exportPersist()), extension: 'dotbench-device' };
    throw new Error('this adapter cannot export the device');
  }
  async importDevice(data: Uint8Array): Promise<void> {
    const a = await this.ensureAdapter();
    if (typeof a.importDevice === 'function') await a.importDevice(data);
    else if (typeof a.importPersist === 'function') a.importPersist(unpackRegions(data));
    else throw new Error('this adapter cannot import a device');
    // the regions are applied when the firmware boots: reboot like a reset
    if (a.appName) await this.restart();
  }
}
